/**
 * Tests {@link ResourceCompiler#filterLanguages(File[])}.
 */
@Test
public void testFilterLanguages() {
    final var resourcesToProcess = new TreeMap<File, Boolean>();
    for (final String file : new String[] { "Errors_en.properties", "Messages_fr.properties", "Errors.properties", "Errors_fr.properties", "ShallIgnore.properties", "Messages_en.properties", "Messages.properties" }) {
        assertNull(resourcesToProcess.put(new File(file), Boolean.FALSE));
    }
    IndexedResourceCompiler.filterLanguages(resourcesToProcess, false);
    final var it = resourcesToProcess.entrySet().iterator();
    Map.Entry<File, Boolean> entry;
    entry = it.next();
    assertEquals("Errors.properties", entry.getKey().getName());
    assertTrue(entry.getValue());
    entry = it.next();
    assertEquals("Messages.properties", entry.getKey().getName());
    assertTrue(entry.getValue());
    entry = it.next();
    assertEquals("ShallIgnore.properties", entry.getKey().getName());
    assertFalse(entry.getValue());
    assertFalse(it.hasNext());
}

