    assertEquals("", c.outputBuffer.toString());
    assertFalse(c.hasUnexpectedFileCount(1, 2));
    assertEquals("", c.outputBuffer.toString());
    assertTrue(c.hasUnexpectedFileCount(2, 3));
    String message = c.outputBuffer.toString();
    assertNotEquals(0, message.length());
}

