    gridToCRS.m00 = 100;
    // Offset
    gridToCRS.m02 = 100;
    final GridCoverage.Evaluator evaluator = createTestCoverage(MathTransforms.linear(gridToCRS)).evaluator();
    evaluator.setWraparoundEnabled(true);
