    final double xmin = -2.0037508342789244E7;
    final GridGeometry target = new GridGeometry(new GridExtent(null, null, new long[] { 2 * width, height }, false), CELL_CENTER, new AffineTransform2D(-xmin / width, 0, 0, 2610000, xmin, -2376500), HardCodedConversions.mercator());
