    env2d = new Envelope2D(HardCodedCRS.WGS84_LATITUDE_FIRST, -90, -180, 180, 360);
    for (WraparoundMethod method : methods) {
        assertToGeometryEquals(env2d, method, -90, -180, -90, 180, 90, 180, 90, -180, -90, -180);
    }
}

