/**
 * Tests the creation of an index color model using explicit range of sample values.
 *
 * @throws TransformException if a sample value cannot be converted.
 */
@Test
public void testRangeAndColors() throws TransformException {
    final var colorizer = new ColorScaleBuilder(List.of(new SimpleEntry<>(NumberRange.create(0, true, 0, true), new Color[] { Color.GRAY }), new SimpleEntry<>(NumberRange.create(1, true, 1, true), new Color[] { ColorModelFactory.TRANSPARENT }), new SimpleEntry<>(NumberRange.create(2, true, 15, true), new Color[] { Color.BLUE, Color.WHITE, Color.RED })), null);
    /*
         * No conversion of sample values should be necessary because the
         * above-given ranges already fit in a 4-bits IndexColormodel.
         */
    assertTrue(colorizer.getSampleToIndexValues().isIdentity());
    final var cm = (IndexColorModel) colorizer.createColorModel(DataType.BYTE, 1, 0);
    final int[] expected = { // Color.GRAY
    0xFF808080, // ColorModelFactory.TRANSPARENT
    0x00000000, // Color.BLUE
    0xFF0000FF, 0xFF2727FF, 0xFF4E4EFF, 0xFF7676FF, 0xFF9D9DFF, 0xFFC4C4FF, 0xFFEBEBFF, 0xFFFFEBEB, 0xFFFFC4C4, 0xFFFF9D9D, 0xFFFF7676, 0xFFFF4E4E, 0xFFFF2727, // Color.RED
    0xFFFF0000 };
    assertEquals(expected.length, cm.getMapSize());
    assertEquals(1, cm.getTransparentPixel());
    for (int i = 0; i < expected.length; i++) {
        assertEquals(expected[i], cm.getRGB(i));
    }
}

/**
 * Tests the creation of an index color model using sample dimensions.
 *
 * @throws TransformException if a sample value cannot be converted.
 */
@Test
public void testSampleDimension() throws TransformException {
    final SampleDimension sd = new SampleDimension.Builder().addQualitative("No data", Float.NaN).addQuantitative("Low temperature", -5, 24, Units.CELSIUS).addQuantitative("Hot temperature", 25, 40, Units.CELSIUS).addQualitative("Error", MathFunctions.toNanFloat(3)).setName("Temperature").build();
    final var colorizer = new ColorScaleBuilder(ColorScaleBuilder.GRAYSCALE, null, true);
    assertTrue(colorizer.initialize(null, sd));
    final var dt = DataType.forDataBufferType(ColorScaleBuilder.TYPE_COMPACT);
    // Must be first.
    final var cm = (IndexColorModel) colorizer.createColorModel(dt, 1, 0);
    /*
         * Test conversion of a few sample values to packed values.
         */
    final MathTransform1D tr = colorizer.getSampleToIndexValues();
    assertFalse(tr.isIdentity());
    assertEquals(0, tr.transform(Float.NaN));
    assertEquals(1, tr.transform(MathFunctions.toNanFloat(3)));
    assertEquals(2, tr.transform(-5), 1E-14);
    assertEquals(255, tr.transform(40), 1E-14);
    /*
         * Verifies a few values from the color map. We test about 1/16 of values.
         * The color map is a simple grayscale, except the two first colors which
         * are transparent.
         */
    assertEquals(256, cm.getMapSize());
    assertEquals(0, cm.getTransparentPixel());
    final int[] expected = { 0, 0x00000000, 1, 0x00000000, 2, 0xFF000000, 16, 0xFF161616, 32, 0xFF2E2E2E, 48, 0xFF474747, 64, 0xFF5F5F5F, 80, 0xFF787878, 96, 0xFF909090, 112, 0xFFA9A9A9, 128, 0xFFC2C2C2, 144, 0xFFDADADA, 160, 0xFFF3F3F3, 176, 0xFF151515, 192, 0xFF444444, 208, 0xFF747474, 224, 0xFFA3A3A3, 240, 0xFFD3D3D3, 255, 0xFFFFFFFF };
    for (int k = 0; k < expected.length; ) {
        final int i = expected[k++];
        final int e = expected[k++];
        assertEquals(e, cm.getRGB(i));
    }
}

/**
 * Tests {@link ImageUtilities#getBounds(RenderedImage)} and {@link ImageUtilities#clipBounds(RenderedImage, Rectangle)}.
 */
@Test
public void testClipBounds() {
    final BufferedImage image = new BufferedImage(5, 4, BufferedImage.TYPE_BYTE_GRAY);
    final Rectangle bounds = ImageUtilities.getBounds(image);
    assertEquals(0, bounds.x);
    assertEquals(0, bounds.y);
    assertEquals(5, bounds.width);
    assertEquals(4, bounds.height);
    bounds.x = -4;
    bounds.y = 1;
    bounds.width = 8;
    bounds.height = 7;
    ImageUtilities.clipBounds(image, bounds);
    assertEquals(0, bounds.x);
    assertEquals(1, bounds.y);
    assertEquals(4, bounds.width);
    assertEquals(3, bounds.height);
}

