    assertEquals("MyISSN", citation.getISSN(), "The ISSN value shall have been added, because new.");
    assertEquals("{NetCDF=“MyNetCDF”, EPSG=“MyEPSG”, ISBN=“NewISBN”, ISSN=“MyISSN”}", identifierMap.toString());
}

