/**
 * Tests the behavior when state is {@link ModifiableMetadata.State#EDITABLE}.
 * Setting new values and overwriting existing values are allowed.
 */
@Test
public void testStateEditable() {
    // Shall be a no-op.
    assertFalse(md.transitionTo(ModifiableMetadata.State.EDITABLE));
    assertEquals(ModifiableMetadata.State.EDITABLE, md.state());
    assertEquals(ModifiableMetadata.State.EDITABLE, identifierState());
    /*
         * Verify conditions given in Javadoc: allow new values and overwriting.
         */
    // New value.
    md.setVolumes(4);
    // Overwriting.
    md.setMediumNote(new SimpleInternationalString("A new note."));
    md.getMediumFormats().add(MediumFormat.TAR);
    // Discard TAR.
    md.setMediumFormats(Set.of(MediumFormat.CPIO));
    md.getMediumFormats().add(MediumFormat.ISO_9660);
    assertPropertiesEqual(4, "A new note.", MediumFormat.CPIO, MediumFormat.ISO_9660);
}

/**
 * Tests the behavior when state is {@link ModifiableMetadata.State#COMPLETABLE}.
 * Setting new values is allowed but overwriting existing values is not allowed.
 */
@Test
public void testStateCompletable() {
    assertTrue(md.transitionTo(ModifiableMetadata.State.COMPLETABLE));
    assertEquals(ModifiableMetadata.State.COMPLETABLE, md.state());
    assertEquals(ModifiableMetadata.State.COMPLETABLE, identifierState());
    RuntimeException e;
    e = assertThrows(UnmodifiableMetadataException.class, () -> md.transitionTo(ModifiableMetadata.State.EDITABLE), "Shall not be allowed to transition back to editable state.");
    assertMessageContains(e);
    /*
         * Verify conditions given in Javadoc: allow new values but not overwriting.
         */
    md.setVolumes(4);
    e = assertThrows(UnmodifiableMetadataException.class, () -> md.setMediumNote(new SimpleInternationalString("A new note.")), "Overwriting an existing value shall not be allowed.");
    assertMessageContains(e, "The original note.");
    e = assertThrows(UnsupportedOperationException.class, () -> md.getMediumFormats().add(MediumFormat.TAR), "Adding a new value shall not be allowed.");
    assertNotNull(e);
    md.setMediumFormats(Set.of(MediumFormat.CPIO));
    e = assertThrows(UnsupportedOperationException.class, () -> md.getMediumFormats().add(MediumFormat.ISO_9660), "Setting a new value shall not be allowed.");
    assertNotNull(e);
    assertPropertiesEqual(4, "The original note.", MediumFormat.CPIO);
}

/**
 * Tests the behavior when state is {@link ModifiableMetadata.State#FINAL}.
 * Setting new values and overwriting existing values are <strong>not</strong> allowed.
 */
