         * Initially empty tree, or tree with only empty element.
         */
    assertTrue(bbox.isEmpty());
    assertTrue(extent.isEmpty());
    assertTrue(scale.isEmpty());
    assertTrue(identification.isEmpty());
    assertTrue(metadata.isEmpty());
