            removeAndAddRecords("TD");
            addRecords("OT", 30);
            /*
                 * Cleaning.
                 */
            stmt.executeUpdate("DROP TABLE \"" + TABLE + '"');
            stmt.close();
            generator.close();
        }
    }
}

