    assertNull(citation.getISBN(), "ISBN shall have been removed.");
    assertTrue(citation.getIdentifiers().isEmpty(), "ISBN shall have been removed.");
    assertArrayEquals(new SimpleEntry<?, ?>[] { new SimpleEntry<>("title", title), new SimpleEntry<>("citedResponsibleParties", List.of(author)) }, map.entrySet().toArray());
    /*
         * Add a value. Result shall be:
         *
         * Citation
         *   ├─Title…………………………………………………… Undercurrent
         *   ├─Cited Responsible Parties
         *   │   └─Individual Name……………… Testsuya Toyoda
         *   └─Presentation Forms………………… document hardcopy
         */
    assertNull(map.put("presentationForm", DOCUMENT_HARDCOPY));
    assertEquals(DOCUMENT_HARDCOPY, getSingleton(citation.getPresentationForms()));
    assertArrayEquals(new SimpleEntry<?, ?>[] { new SimpleEntry<>("title", title), new SimpleEntry<>("citedResponsibleParties", List.of(author)), new SimpleEntry<>("presentationForms", Set.of(DOCUMENT_HARDCOPY)) }, map.entrySet().toArray());
    /*
         * Add back the ISBN value. Result shall be:
         *
         * Citation
         *   ├─Title…………………………………………………… Undercurrent
         *   ├─Identifiers…………………………………… 9782505004509
         *   ├─Cited Responsible Parties
         *   │   └─Individual Name……………… Testsuya Toyoda
         *   ├─Presentation Forms………………… document hardcopy
         *   └─ISBN……………………………………………………… 9782505004509
         */
    assertNull(map.put("ISBN", "9782505004509"));
    assertEquals("9782505004509", citation.getISBN());
    assertEquals(1, citation.getIdentifiers().size(), "ISBN shall appears in the identifier list.");
    assertArrayEquals(new SimpleEntry<?, ?>[] { new SimpleEntry<>("title", title), new SimpleEntry<>("identifiers", citation.getIdentifiers()), new SimpleEntry<>("citedResponsibleParties", List.of(author)), new SimpleEntry<>("presentationForms", Set.of(DOCUMENT_HARDCOPY)), new SimpleEntry<>("ISBN", "9782505004509") }, map.entrySet().toArray());
}

