/**
 * Tests the comparison of {@link NilObject} instances.
 */
@Test
public void testNilObjectComparison() {
    final Citation e1 = NilReason.TEMPLATE.createNilObject(Citation.class);
    final Citation e2 = NilReason.MISSING.createNilObject(Citation.class);
    final Citation e3 = NilReason.TEMPLATE.createNilObject(Citation.class);
    assertEquals(e1.hashCode(), e3.hashCode());
    assertFalse(e1.hashCode() == e2.hashCode());
    assertEquals(e1, e3);
    assertFalse(e1.equals(e2));
    assertInstanceOf(LenientComparable.class, e1);
    final LenientComparable c = (LenientComparable) e1;
    assertTrue(c.equals(e3, ComparisonMode.STRICT));
    assertFalse(c.equals(e2, ComparisonMode.STRICT));
    assertFalse(c.equals(e2, ComparisonMode.BY_CONTRACT));
    assertTrue(c.equals(e2, ComparisonMode.IGNORE_METADATA));
    assertTrue(c.equals(e2, ComparisonMode.APPROXIMATE));
    assertTrue(c.equals(e2, ComparisonMode.DEBUG));
    // Following object should alway be different because it does not implement the same interface.
    final Responsibility r1 = NilReason.TEMPLATE.createNilObject(Responsibility.class);
    assertFalse(c.equals(r1, ComparisonMode.STRICT));
    assertFalse(c.equals(r1, ComparisonMode.BY_CONTRACT));
    assertFalse(c.equals(r1, ComparisonMode.IGNORE_METADATA));
    assertFalse(c.equals(r1, ComparisonMode.APPROXIMATE));
    assertFalse(c.equals(r1, ComparisonMode.DEBUG));
}

/**
 * Tests the {@link DocumentComparator#ignoredAttributes} and {@link DocumentComparator#ignoredNodes} sets.
 *
 * @throws Exception if an error occurred while reading the XML.
 */
@Test
public void testIgnore() throws Exception {
    final DocumentComparator cmp = new DocumentComparator("<body>\n" + "  <form id=\"MyForm\">\n" + "    <table cellpading=\"1\">\n" + "      <tr><td>foo</td></tr>\n" + "    </table>\n" + "  </form>\n" + "</body>", "<body>\n" + "  <form id=\"MyForm\">\n" + "    <table cellpading=\"2\">\n" + "      <tr><td>foo</td></tr>\n" + "    </table>\n" + "  </form>\n" + "</body>");
    assertFail("Shall fail because the \"cellpading\" attribute value is different.", cmp);
    // Following comparison should not fail anymore.
    cmp.ignoredAttributes.add("cellpading");
    cmp.compare();
    cmp.ignoredAttributes.clear();
    cmp.ignoredAttributes.add("bgcolor");
    assertFail("The \"cellpading\" attribute should not be ignored anymore.", cmp);
    // Ignore the table node, which contains the faulty attribute.
    cmp.ignoredNodes.add("table");
    cmp.compare();
    // Ignore the form node and all its children.
    cmp.ignoredNodes.clear();
    cmp.ignoredNodes.add("form");
    cmp.compare();
}

/**
 * Verifies that comparisons of XML documents compare the namespace URIs, not the prefixes.
 *
 * @see javax.xml.parsers.DocumentBuilderFactory#setNamespaceAware(boolean)
 *
 * @throws Exception if an error occurred while reading the XML.
 */
@Test
public void testNamespaceAware() throws Exception {
    DocumentComparator cmp = new DocumentComparator("<ns1:body xmlns:ns1=\"http://myns1\" xmlns:ns2=\"http://myns2\">\n" + "  <ns1:table ns2:cellpading=\"1\"/>\n" + "</ns1:body>", "<ns4:body xmlns:ns4=\"http://myns1\" xmlns:ns3=\"http://myns2\">\n" + "  <ns4:table ns3:cellpading=\"1\"/>\n" + "</ns4:body>");
    // Following comparison should not fail anymore.
    cmp.ignoredAttributes.add("http://www.w3.org/2000/xmlns:*");
    cmp.compare();
    /*
         * Opposite case: same prefix, but different URL.
         * The XML comparison is expected to fail.
         */
    cmp = new DocumentComparator("<ns1:body xmlns:ns1=\"http://myns1\" xmlns:ns2=\"http://myns2\">\n" + "  <ns1:table ns2:cellpading=\"1\"/>\n" + "</ns1:body>", "<ns1:body xmlns:ns1=\"http://myns1\" xmlns:ns2=\"http://myns3\">\n" + "  <ns1:table ns2:cellpading=\"1\"/>\n" + "</ns1:body>");
    // Following comparison should not fail anymore.
    cmp.ignoredAttributes.add("http://www.w3.org/2000/xmlns:*");
    assertFail("Shall fail because the \"cellpading\" attribute has a different namespace.", cmp);
}

