/**
 * Tests {@link FrenchProfile#toAFNOR(Object)} with {@link Constraints},
 * {@link LegalConstraints} and  {@link SecurityConstraints} objects.
 */
@Test
public void testConstraintsToAFNOR() {
    Constraints std, fra;
    std = new DefaultConstraints("Some constraints.");
    fra = (Constraints) FrenchProfile.toAFNOR(std);
    assertNotSame(std, fra);
    assertSame(fra, FrenchProfile.toAFNOR(fra));
    assertEquals("Some constraints.", getSingleton(fra.getUseLimitations()).toString());
    std = new DefaultLegalConstraints("Some legal constraints.");
    fra = (LegalConstraints) FrenchProfile.toAFNOR(std);
    assertNotSame(std, fra);
    assertSame(fra, FrenchProfile.toAFNOR(fra));
    assertEquals("Some legal constraints.", getSingleton(fra.getUseLimitations()).toString());
    std = new DefaultSecurityConstraints("Some security constraints.");
    fra = (SecurityConstraints) FrenchProfile.toAFNOR(std);
    assertNotSame(std, fra);
    assertSame(fra, FrenchProfile.toAFNOR(fra));
    assertEquals("Some security constraints.", getSingleton(fra.getUseLimitations()).toString());
}

/**
 * Tests {@link FrenchProfile#toAFNOR(ReferenceSystem, boolean)}.
 */
@Test
public void testReferenceSystemToAFNOR() {
    ReferenceSystem std, fra;
    std = new ReferenceSystemMetadata(new DefaultIdentifier("EPSG", "4326", null));
    fra = FrenchProfile.toAFNOR(std, false);
    assertInstanceOf(DirectReferenceSystem.class, fra);
    assertSame(fra, FrenchProfile.toAFNOR(fra));
    fra = FrenchProfile.toAFNOR(std, true);
    assertInstanceOf(IndirectReferenceSystem.class, fra);
    assertSame(fra, FrenchProfile.toAFNOR(fra));
}

/**
 * Tests marshalling and unmarshalling of a XML fragment.
 *
 * @throws JAXBException if an error occurred during (un)marshalling.
 *
 * @see <a href="https://issues.apache.org/jira/browse/SIS-404">SIS-404</a>
 */
@Test
public void testMarshalling() throws JAXBException {
    final String xml = "<fra:FRA_DataIdentification xmlns:gmd=\"http://www.isotc211.org/2005/gmd\"" + " xmlns:gco=\"http://www.isotc211.org/2005/gco\"" + " xmlns:fra=\"http://www.cnig.gouv.fr/2005/fra\">\n" + "  <gmd:citation>\n" + "    <gmd:CI_Citation>\n" + "      <gmd:title>\n" + "        <gco:CharacterString>Main documentation.</gco:CharacterString>\n" + "      </gmd:title>\n" + "    </gmd:CI_Citation>\n" + "  </gmd:citation>\n" + "  <fra:relatedCitation>\n" + "    <gmd:CI_Citation>\n" + "      <gmd:title>\n" + "        <gco:CharacterString>Related documentation.</gco:CharacterString>\n" + "      </gmd:title>\n" + "    </gmd:CI_Citation>\n" + "  </fra:relatedCitation>\n" + "</fra:FRA_DataIdentification>";
    final DataIdentification id = unmarshal(DataIdentification.class, xml);
    assertTitleEquals("Main documentation.", id.getCitation(), "citation");
    assertTitleEquals("Related documentation.", getSingleton(id.getRelatedCitations()), "relatedCitations");
    final String actual = marshal(id, VERSION_2007);
    assertXmlEquals(xml, actual, "xmlns:*");
}

