/**
 * Tests the production of a warning messages when the WKT contains unknown elements.
 *
 * @throws ParseException if the parsing failed.
 */
@Test
public void testWarnings() throws ParseException {
    final GeographicCRS crs = parseIgnoreWarnings(GeographicCRS.class, "GEOGCS[“WGS 84”,\n" + "  DATUM[“World Geodetic System 1984”,\n" + "    SPHEROID[“WGS84”, 6378137.0, 298.257223563, Ext1[“foo”], Ext2[“bla”]]],\n" + // Inaccurate scale factor.
    "    PRIMEM[“Greenwich”, 0.0, Intruder[“unknown”], UNIT[“degree”, 0.01746]],\n" + "  UNIT[“degree”, 0.017453292519943295], Intruder[“foo”]]");
    verifyGeographicCRS(0, crs);
    final Warnings warnings = parser.getAndClearWarnings(crs);
    assertNotNull(warnings, "warnings");
    assertTrue(warnings.getExceptions().isEmpty());
    assertEquals("WGS 84", warnings.getRootElement());
    assertArrayEquals(new String[] { "Intruder", "Ext1", "Ext2" }, warnings.getUnknownElements().toArray());
    assertArrayEquals(new String[] { "PRIMEM", "GEOGCS" }, warnings.getUnknownElementLocations("Intruder").toArray());
    assertArrayEquals(new String[] { "SPHEROID" }, warnings.getUnknownElementLocations("Ext1").toArray());
    assertArrayEquals(new String[] { "SPHEROID" }, warnings.getUnknownElementLocations("Ext2").toArray());
    assertMultilinesEquals("Parsing of “WGS 84” done, but some elements were ignored.\n" + " • Unexpected scale factor 0.01746 for unit of measurement “°”.\n" + " • The text contains unknown elements:\n" + "    ‣ “Intruder” in PRIMEM, GEOGCS.\n" + "    ‣ “Ext1” in SPHEROID.\n" + "    ‣ “Ext2” in SPHEROID.", warnings.toString(Locale.US));
    assertMultilinesEquals("La lecture de « WGS 84 » a été faite, mais en ignorant certains éléments.\n" + " • Le facteur d’échelle 0,01746 est inattendu pour l’unité de mesure « ° ».\n" + " • Le texte contient des éléments inconnus :\n" + "    ‣ « Intruder » dans PRIMEM, GEOGCS.\n" + "    ‣ « Ext1 » dans SPHEROID.\n" + "    ‣ « Ext2 » dans SPHEROID.", warnings.toString(Locale.FRANCE));
}

/**
 * Tests {@link MathTransformParser#completeUnitFactor(Unit, double)}.
 * This is not used directly by {@link MathTransformParser}, but is needed by subclass.
 *
 * @see <a href="https://issues.apache.org/jira/browse/SIS-377">SIS-377</a>
 * @see <a href="https://issues.apache.org/jira/browse/SIS-433">SIS-433</a>
 */
@Test
public void testCompleteUnitFactor() {
    // SIS-377
    assertEquals(0.017453292519943295, MathTransformParser.completeUnitFactor(Units.RADIAN, 0.01745329252));
    // Not the right kind of units.
    assertEquals(0.01745329252, MathTransformParser.completeUnitFactor(Units.METRE, 0.01745329252));
    // Check there is no confusion with US survey foot.
    assertEquals(0.3048, MathTransformParser.completeUnitFactor(Units.METRE, 0.3048));
    // US survey foot.
    assertEquals(0.30480060960121924, MathTransformParser.completeUnitFactor(Units.METRE, 0.3048006096));
    // British foot (1936).
    assertEquals(0.3048007491, MathTransformParser.completeUnitFactor(Units.METRE, 0.3048007491));
    // Indian foot (1937).
    assertEquals(0.30479841, MathTransformParser.completeUnitFactor(Units.METRE, 0.30479841));
    assertEquals(0.3047, MathTransformParser.completeUnitFactor(Units.METRE, 0.3047));
}

