    for (int numRow = 2; numRow <= size; numRow++) {
        for (int numCol = 2; numCol <= size; numCol++) {
            final Matrix matrix = Matrices.createZero(numRow, numCol);
            for (int j = 0; j < numRow; j++) {
                for (int i = 0; i < numCol; i++) {
