/**
 * Verifies the vertical datum enumeration.
 */
@Test
@SuppressWarnings("deprecation")
public void testVertical() {
    for (final CommonCRS.Vertical e : CommonCRS.Vertical.values()) {
        final RealizationMethod method;
        final String axisName, datumName;
        switch(e) {
            case NAVD88:
                axisName = AxisNames.GRAVITY_RELATED_HEIGHT;
                datumName = "North American Vertical Datum 1988";
                method = RealizationMethod.GEOID;
                break;
            case BAROMETRIC:
                axisName = "Barometric altitude";
                datumName = "Constant pressure surface";
                method = RealizationMethod.valueOf("BAROMETRIC");
                break;
            case MEAN_SEA_LEVEL:
                axisName = AxisNames.GRAVITY_RELATED_HEIGHT;
                datumName = "Mean Sea Level";
                method = RealizationMethod.TIDAL;
                break;
            case DEPTH:
                axisName = AxisNames.DEPTH;
                datumName = "Mean Sea Level";
                method = RealizationMethod.TIDAL;
                break;
            case ELLIPSOIDAL:
                axisName = AxisNames.ELLIPSOIDAL_HEIGHT;
                datumName = "Ellipsoid";
                method = VerticalDatumTypes.ellipsoidal();
                break;
            case OTHER_SURFACE:
                axisName = "Height";
                datumName = "Other surface";
                method = null;
                break;
            default:
                throw new AssertionError(e);
        }
        final String name = e.name();
        final VerticalDatum datum = e.datum();
        final VerticalCRS crs = e.crs();
        if (e.isEPSG) {
            /*
                 * BAROMETRIC and ELLIPSOIDAL uses an axis named "Height", which is not a valid
                 * axis name according ISO 19111. We skip the validation test for those enums.
                 */
            Validators.validate(crs);
        }
        // Datum before CRS creation.
        assertSame(datum, e.datum(), name);
        // Datum after CRS creation.
        assertSame(crs.getDatum(), e.datum(), name);
        assertEquals(datumName, datum.getName().getCode(), name);
        assertEquals(axisName, crs.getCoordinateSystem().getAxis(0).getName().getCode(), name);
        if (!e.isEPSG) {
            // Because the information is not in EPSG database 9.x.
            assertEquals(method, datum.getRealizationMethod().orElse(null), name);
        }
    }
}

/**
 * Verifies the epoch values of temporal enumeration compared to the Julian epoch.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Julian_day">Wikipedia: Julian day</a>
 */
@Test
public void testTemporal() {
    final var julianEpoch = (Instant) CommonCRS.Temporal.JULIAN.datum().getOrigin();
    final double SECONDS_PER_DAY = Constants.SECONDS_PER_DAY;
    final double julianEpochSecond = julianEpoch.getEpochSecond() / SECONDS_PER_DAY;
    assertTrue(julianEpochSecond < 0);
    /*
         * We need to use `java.text.DateFormat` rather than `Instant.parse(String)` because
         * they have different policy regarding the calendar for dates before October 15, 1582.
         * The `java.time` classes use the proleptic Gregorian calendar while `java.text` uses
         * the prolectic Julian calendar. The latter is what we need for this test.
         */
    final var dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.CANADA);
    dateFormat.setTimeZone(TimeZone.getTimeZone(UTC));
    dateFormat.setLenient(false);
    for (final CommonCRS.Temporal e : CommonCRS.Temporal.values()) {
        final String epoch;
        final double days;
        switch(e) {
            // Fall through
            case JAVA:
            case UNIX:
                epoch = "1970-01-01 00:00:00";
                days = 2440587.5;
                break;
            case TRUNCATED_JULIAN:
                epoch = "1968-05-24 00:00:00";
                days = 2440000.5;
                break;
            case DUBLIN_JULIAN:
                epoch = "1899-12-31 12:00:00";
                days = 2415020.0;
                break;
            case MODIFIED_JULIAN:
                epoch = "1858-11-17 00:00:00";
                days = 2400000.5;
                break;
            case JULIAN:
                epoch = "4713-01-01 12:00:00";
                days = 0;
                break;
            case TROPICAL_YEAR:
                epoch = "2000-01-01 00:00:00";
                days = 2451544.5;
                break;
            default:
                throw new AssertionError(e);
        }
        final String name = e.name();
        final TemporalDatum datum = e.datum();
        final TemporalCRS crs = e.crs();
        final Instant origin = assertInstanceOf(Instant.class, datum.getOrigin());
        Validators.validate(crs);
        // Datum before CRS creation.
        assertSame(datum, e.datum(), name);
        // Datum after CRS creation.
        assertSame(crs.getDatum(), e.datum(), name);
        assertEquals(epoch, dateFormat.format(Date.from(origin)), name);
        assertEquals(days, origin.getEpochSecond() / SECONDS_PER_DAY - julianEpochSecond, name);
        switch(e) {
            case JAVA:
                {
                    assertNameContains(datum, "Unix/POSIX");
                    assertNameContains(crs, "Java");
                    break;
                }
            case UNIX:
                {
                    assertNameContains(datum, "Unix/POSIX");
                    assertNameContains(crs, "Unix/POSIX");
                    break;
                }
        }
    }
}

