 *
 * @see <a href="https://issues.apache.org/jira/browse/SIS-303">SIS-303</a>
 */
@Test
@SuppressWarnings("ResultOfObjectAllocationIgnored")
public void testEllipsoidalHeight() {
    final Map<String, Object> properties = new HashMap<>(4);
    assertNull(properties.put(DefaultCompoundCRS.LOCALE_KEY, Locale.ENGLISH));
    assertNull(properties.put(DefaultCompoundCRS.NAME_KEY, "3D"));
    var e = assertThrows(IllegalArgumentException.class, () -> new DefaultCompoundCRS(properties, HardCodedCRS.WGS84, HardCodedCRS.ELLIPSOIDAL_HEIGHT), "Should not allow construction with ellipsoidal height.");
    assertEquals("Compound coordinate reference systems should not contain ellipsoidal height. " + "Use a three-dimensional geographic system instead.", e.getMessage());
    /*
         * We allow an ellipsoidal height if there is no horizontal CRS.
