    assertEquals(WKTKeywords.GeodeticCRS, DefaultDerivedCRS.getTypeKeyword(null, HardCodedCRS.WGS84, HardCodedCS.GEODETIC_2D));
    // Using consistent arguments but one more dimension.
    assertEquals(WKTKeywords.GeodeticCRS, DefaultDerivedCRS.getTypeKeyword(null, HardCodedCRS.WGS84, HardCodedCS.GEODETIC_3D));
    // Using consistent arguments.
    assertEquals(WKTKeywords.GeodeticCRS, DefaultDerivedCRS.getTypeKeyword(null, HardCodedCRS.GEOCENTRIC, HardCodedCS.CARTESIAN_3D));
    // Using consistent arguments but one less dimension.
    assertEquals(WKTKeywords.GeodeticCRS, DefaultDerivedCRS.getTypeKeyword(null, HardCodedCRS.GEOCENTRIC, HardCodedCS.CARTESIAN_2D));
    // Using different coordinate system type.
    assertEquals(WKTKeywords.GeodeticCRS, DefaultDerivedCRS.getTypeKeyword(null, HardCodedCRS.GEOCENTRIC, HardCodedCS.SPHERICAL));
    // Using different coordinate system type.
    assertEquals(WKTKeywords.GeodeticCRS, DefaultDerivedCRS.getTypeKeyword(null, HardCodedCRS.WGS84, HardCodedCS.CARTESIAN_2D));
    // Using illegal coordinate system type.
    assertNull(DefaultDerivedCRS.getTypeKeyword(null, HardCodedCRS.WGS84, HardCodedCS.GRAVITY_RELATED_HEIGHT));
}

