public void testGetAuthorityCodes() throws FactoryException {
    assertSetEquals(List.of(StandardDefinitions.GREENWICH), EPSGFactoryFallback.INSTANCE.getAuthorityCodes(PrimeMeridian.class));
    assertSetEquals(List.of("7030", "7043", "7019", "7008", "7022", "7048"), EPSGFactoryFallback.INSTANCE.getAuthorityCodes(Ellipsoid.class));
    assertSetEquals(List.of("6326", "6322", "6269", "6267", "6258", "6230", "6019", "6047", "5100", "5103"), EPSGFactoryFallback.INSTANCE.getAuthorityCodes(Datum.class));
