    assertSetEquals(List.of("6404"), EPSGFactoryFallback.INSTANCE.getAuthorityCodes(SphericalCS.class));
    assertSetEquals(List.of("6500", "4400", "1026", "1027"), EPSGFactoryFallback.INSTANCE.getAuthorityCodes(CartesianCS.class));
    assertSetEquals(List.of("4326", "4322", "4019", "4047", "4269", "4267", "4258", "4230", "4979", "4985", "4937"), EPSGFactoryFallback.INSTANCE.getAuthorityCodes(GeographicCRS.class));
    assertSetEquals(List.of("5714", "5715", "5703"), EPSGFactoryFallback.INSTANCE.getAuthorityCodes(VerticalCRS.class));
    /*
         * Geodetic CRS include geographic CRS with the addition of the following.
         */
    Set<String> geographic = EPSGFactoryFallback.INSTANCE.getAuthorityCodes(GeographicCRS.class);
    Set<String> geodetic = EPSGFactoryFallback.INSTANCE.getAuthorityCodes(GeodeticCRS.class);
    assertTrue(geodetic.containsAll(geographic));
