        throw e.unwrapOrRethrow(FactoryException.class);
    }
    assertSetEquals(List.of("CRS:1", "CRS:27", "CRS:83", "CRS:84", "CRS:88", "AUTO2:42001", "AUTO2:42002", "AUTO2:42003", "AUTO2:42004", "AUTO2:42005", "OGC:JulianDate", "OGC:TruncatedJulianDate", "OGC:UnixTime"), factory.getAuthorityCodes(CoordinateReferenceSystem.class));
    assertSetEquals(List.of("AUTO2:42001", "AUTO2:42002", "AUTO2:42003", "AUTO2:42004", "AUTO2:42005"), factory.getAuthorityCodes(ProjectedCRS.class));
    assertSetEquals(List.of("CRS:27", "CRS:83", "CRS:84"), factory.getAuthorityCodes(GeographicCRS.class));
