    assertSetEquals(List.of("OGC:JulianDate", "OGC:TruncatedJulianDate", "OGC:UnixTime"), factory.getAuthorityCodes(TemporalCRS.class));
    assertSetEquals(List.of("CRS:1"), factory.getAuthorityCodes(EngineeringCRS.class));
    final Set<String> codes = factory.getAuthorityCodes(GeographicCRS.class);
    assertFalse(codes.contains("CRS:1"));
    assertTrue(codes.contains("CRS:27"));
    assertTrue(codes.contains("CRS:83"));
