/**
 * Tests step-by-step the creation of a new projected coordinate reference systems.
 * This test creates every objects itself and compares with expected WKT 1 after each step.
 *
 * <p>Note that practical applications may use existing constants declared in the
 * {@link CommonCRS} class instead of creating everything like this test does.</p>
 *
 * @throws FactoryException if the creation of a geodetic component failed.
 */
@Test
public void testStepByStepCreation() throws FactoryException {
    final CRSFactory crsFactory = factories.getFactory(CRSFactory.class).orElseThrow();
    final CSFactory csFactory = factories.getFactory(CSFactory.class).orElseThrow();
    final DatumFactory datumFactory = factories.getFactory(DatumFactory.class).orElseThrow();
    /*
         * List of all objects to be created in this test.
         */
    final Unit<Length> linearUnit;
    final Unit<Angle> angularUnit;
    final Ellipsoid ellipsoid;
    final PrimeMeridian meridian;
    final GeodeticDatum datum;
    final CoordinateSystemAxis longitude, latitude, easting, northing;
    final EllipsoidalCS geographicCS;
    final GeographicCRS geographicCRS;
    final OperationMethod method;
    final ParameterValueGroup parameters;
    final Conversion projection;
    final CartesianCS projectedCS;
    final ProjectedCRS projectedCRS;
    /*
         * Prime meridian
         */
    angularUnit = Units.DEGREE;
    meridian = datumFactory.createPrimeMeridian(name("Greenwich"), 0, angularUnit);
    assertWktEquals(Convention.WKT1, "PRIMEM[“Greenwich”, 0.0]", meridian);
    /*
         * Ellipsoid
         */
    linearUnit = Units.METRE;
    ellipsoid = datumFactory.createEllipsoid(name("Airy1830"), 6377563.396, 6356256.910, linearUnit);
    assertWktEquals(Convention.WKT1, "SPHEROID[“Airy1830”, 6377563.396, 299.3249753150345]", ellipsoid);
    /*
         * Geodetic reference frame
         */
    datum = datumFactory.createGeodeticDatum(name("Airy1830"), ellipsoid, meridian);
    assertWktEquals(Convention.WKT1, "DATUM[“Airy1830”,\n" + "  SPHEROID[“Airy1830”, 6377563.396, 299.3249753150345]]", datum);
    /*
         * Base coordinate reference system
         */
    longitude = csFactory.createCoordinateSystemAxis(name("Longitude"), "long", AxisDirection.EAST, angularUnit);
    latitude = csFactory.createCoordinateSystemAxis(name("Latitude"), "lat", AxisDirection.NORTH, angularUnit);
    geographicCS = csFactory.createEllipsoidalCS(name("Ellipsoidal"), longitude, latitude);
    geographicCRS = crsFactory.createGeographicCRS(name("Airy1830"), datum, geographicCS);
    assertWktEquals(Convention.WKT1, "GEOGCS[“Airy1830”,\n" + "  DATUM[“Airy1830”,\n" + "    SPHEROID[“Airy1830”, 6377563.396, 299.3249753150345]],\n" + "    PRIMEM[“Greenwich”, 0.0],\n" + "  UNIT[“degree”, 0.017453292519943295],\n" + "  AXIS[“Longitude”, EAST],\n" + "  AXIS[“Latitude”, NORTH]]", geographicCRS);
    /*
         * Defining conversion
         */
    method = DefaultMathTransformFactory.provider().getOperationMethod("Transverse_Mercator");
    parameters = method.getParameters().createValue();
    parameters.parameter("semi_major").setValue(ellipsoid.getSemiMajorAxis());
    parameters.parameter("semi_minor").setValue(ellipsoid.getSemiMinorAxis());
    parameters.parameter("central_meridian").setValue(49);
    parameters.parameter("latitude_of_origin").setValue(-2);
    parameters.parameter("false_easting").setValue(400000);
    parameters.parameter("false_northing").setValue(-100000);
    projection = new DefaultConversion(name("GBN grid"), method, null, parameters);
    /*
         * Projected coordinate reference system
         */
    easting = csFactory.createCoordinateSystemAxis(name("Easting"), "x", AxisDirection.EAST, linearUnit);
    northing = csFactory.createCoordinateSystemAxis(name("Northing"), "y", AxisDirection.NORTH, linearUnit);
    projectedCS = csFactory.createCartesianCS(name("Cartesian"), easting, northing);
    projectedCRS = crsFactory.createProjectedCRS(name("Great_Britian_National_Grid"), geographicCRS, projection, projectedCS);
    assertWktEquals(Convention.WKT1, "PROJCS[“Great_Britian_National_Grid”,\n" + "  GEOGCS[“Airy1830”,\n" + "    DATUM[“Airy1830”,\n" + "      SPHEROID[“Airy1830”, 6377563.396, 299.3249753150345]],\n" + "      PRIMEM[“Greenwich”, 0.0],\n" + "    UNIT[“degree”, 0.017453292519943295],\n" + "    AXIS[“Longitude”, EAST],\n" + "    AXIS[“Latitude”, NORTH]],\n" + "  PROJECTION[“Transverse_Mercator”, AUTHORITY[“EPSG”, “9807”]],\n" + "  PARAMETER[“latitude_of_origin”, -2.0],\n" + "  PARAMETER[“central_meridian”, 49.0],\n" + "  PARAMETER[“scale_factor”, 1.0],\n" + "  PARAMETER[“false_easting”, 400000.0],\n" + "  PARAMETER[“false_northing”, -100000.0],\n" + "  UNIT[“metre”, 1],\n" + "  AXIS[“Easting”, EAST],\n" + "  AXIS[“Northing”, NORTH]]", projectedCRS);
}

/**
 * Tests the {@link IdentifiedObjectFinder#findSingleton(IdentifiedObject)} method.
 *
 * @throws FactoryException if the creation of a CRS failed.
 */
@Test
public void testFindSingleton() throws FactoryException {
    final GeographicCRS CRS84 = factory.createGeographicCRS("CRS:84");
    final IdentifiedObjectFinder finder = factory.newIdentifiedObjectFinder();
    assertEquals(IdentifiedObjectFinder.Domain.VALID_DATASET, finder.getSearchDomain(), "Newly created finder should default to full scan.");
    finder.setSearchDomain(IdentifiedObjectFinder.Domain.DECLARATION);
    assertSame(CRS84, finder.findSingleton(CRS84), "Should find without the need for scan, since we can use the CRS:84 identifier.");
    finder.setSearchDomain(IdentifiedObjectFinder.Domain.VALID_DATASET);
    assertSame(CRS84, finder.findSingleton(CRS84), "Allowing scanning should not make any difference for this CRS84 instance.");
    /*
         * Same test as above, using a CRS without identifier.
         * The intent is to force a full scan.
         */
    final CoordinateReferenceSystem search = new DefaultGeographicCRS(Map.of(DefaultGeographicCRS.NAME_KEY, CRS84.getName()), CRS84.getDatum(), CRS84.getDatumEnsemble(), CRS84.getCoordinateSystem());
    // Required condition for next test.
    assertEqualsIgnoreMetadata(CRS84, search);
    finder.setSearchDomain(IdentifiedObjectFinder.Domain.DECLARATION);
    assertNull(finder.findSingleton(search), "Should not find WGS84 without a full scan, since it does not contains the CRS:84 identifier.");
    finder.setSearchDomain(IdentifiedObjectFinder.Domain.VALID_DATASET);
    assertSame(CRS84, finder.findSingleton(search), "A full scan should allow us to find WGS84, since it is equal ignoring metadata to CRS:84.");
}

