/**
 * Tests {@link Solver#inverse(org.opengis.referencing.operation.Matrix, boolean)}
 * with a square matrix that contains a {@link Double#NaN} value.
 *
 * @throws NoninvertibleMatrixException if an unexpected error occurred while inverting the matrix.
 */
@Test
public void testInverseWithNaN() throws NoninvertibleMatrixException {
    /*
         * Just for making sure that our matrix is correct.
         */
    matrix = Matrices.create(5, 5, new double[] { 20, 0, 0, 0, -3000, 0, -20, 0, 0, 4000, 0, 0, 0, 2, 20, 0, 0, 400, 0, 2000, 0, 0, 0, 0, 1 });
    double[] expected = { 0.05, 0, 0, 0, 150, 0, -0.05, 0, 0, 200, 0, 0, 0, 0.0025, -5, 0, 0, 0.5, 0, -10, 0, 0, 0, 0, 1 };
    MatrixSIS inverse = Solver.inverse(matrix);
    assertEqualsElements(expected, 5, 5, inverse, TOLERANCE);
    /*
         * Set a scale factor to NaN. The translation term for the corresponding
         * dimension become unknown, so it must become NaN in the inverse matrix.
         */
    matrix = Matrices.create(5, 5, new double[] { 20, 0, 0, 0, -3000, 0, -20, 0, 0, 4000, // Translation is 20: cannot be converted.
    0, // Translation is 20: cannot be converted.
    0, // Translation is 20: cannot be converted.
    0, // Translation is 20: cannot be converted.
    NaN, // Translation is 20: cannot be converted.
    20, 0, 0, 400, 0, 2000, 0, 0, 0, 0, 1 });
    expected = new double[] { 0.05, 0, 0, 0, 150, 0, -0.05, 0, 0, 200, 0, 0, 0, 0.0025, -5, 0, 0, NaN, 0, NaN, 0, 0, 0, 0, 1 };
    inverse = Solver.inverse(matrix);
    assertEqualsElements(expected, 5, 5, inverse, TOLERANCE);
    /*
         * Set a scale factor to NaN with translation equals to 0.
         * The zero value should be preserved, since 0 × any == 0
         * (ignoring infinities).
         */
    matrix = Matrices.create(5, 5, new double[] { 20, 0, 0, 0, -3000, 0, -20, 0, 0, 4000, // Translation is 0: should be preserved.
    0, // Translation is 0: should be preserved.
    0, // Translation is 0: should be preserved.
    0, // Translation is 0: should be preserved.
    NaN, // Translation is 0: should be preserved.
    0, 0, 0, 400, 0, 2000, 0, 0, 0, 0, 1 });
    expected = new double[] { 0.05, 0, 0, 0, 150, 0, -0.05, 0, 0, 200, 0, 0, 0, 0.0025, -5, 0, 0, NaN, 0, 0, 0, 0, 0, 0, 1 };
    inverse = Solver.inverse(matrix);
    assertEqualsElements(expected, 5, 5, inverse, TOLERANCE);
    /*
         * Set a translation term to NaN. The translation should be NaN in
         * the inverse matrix too, but the scale factor can still be compute.
         */
    matrix = Matrices.create(5, 5, new double[] { 20, 0, 0, 0, -3000, 0, -20, 0, 0, 4000, 0, 0, 0, 2, NaN, 0, 0, 400, 0, 2000, 0, 0, 0, 0, 1 });
    expected = new double[] { 0.05, 0, 0, 0, 150, 0, -0.05, 0, 0, 200, 0, 0, 0, 0.0025, -5, 0, 0, 0.5, 0, NaN, 0, 0, 0, 0, 1 };
    inverse = Solver.inverse(matrix);
    assertEqualsElements(expected, 5, 5, inverse, TOLERANCE);
}

/**
 * Tests the unitary projection on a sphere.
 *
 * @throws FactoryException if an error occurred while creating the map projection.
 * @throws TransformException if an error occurred while projecting a point.
 */
@Test
public void testSphere() throws FactoryException, TransformException {
    createCompleteProjection(new org.apache.sis.referencing.operation.provider.AlbersEqualArea(), // Semi-major axis from Snyder table 15
    6370997, // Semi-minor axis
    6370997, // Central meridian
    0, // Latitude of origin
    0, // Standard parallel 1 (from Snyder table 15)
    29.5, // Standard parallel 2 (from Snyder table 15)
    45.5, // Scale factor (none)
    NaN, // False easting
    0, // False northing
    0);
    // Approximately 100 metres.
    final double delta = toRadians(100.0 / 60) / 1852;
    derivativeDeltas = new double[] { delta, delta };
    toleranceModifier = ToleranceModifier.PROJECTION;
    tolerance = Formulas.LINEAR_TOLERANCE;
    final AlbersEqualArea kernel = (AlbersEqualArea) getKernel();
    assertTrue(isSpherical(kernel));
    // Expected 'n' value from Snyder table 15.
    assertEquals(0.6028370, kernel.nm, 0.5E-7);
    /*
         * When stepping into the AlbersEqualArea.Sphere.transform(…) method with a debugger, the
         * expected value of 6370997*ρ/n is 6910941 (value taken from ρ column in Snyder table 15).
         */
    verifyTransform(new double[] { 0, 50 }, new double[] { 0, 5373933.180 });
    /*
         * Expect 6370997*ρ/n  ≈  8022413   (can be verified only with the debugger)
         */
    verifyTransform(new double[] { 0, 40 }, new double[] { 0, 4262461.266 });
    /*
         * Expect 6370997*ρ/n  ≈  9695749   (can be verified only with the debugger)
         */
    verifyTransform(new double[] { 0, 25 }, new double[] { 0, 2589125.654 });
    /*
         * Verify consistency with random points.
         */
    // Minimal input coordinate values
    verifyInDomain(// Minimal input coordinate values
    new double[] { -20, 20 }, // Maximal input coordinate values
    new double[] { +20, 50 }, // Number of points to test
    new int[] { 5, 5 }, TestUtilities.createRandomNumberGenerator());
}

/**
 * Tests the unitary projection on an ellipse.
 *
 * @throws FactoryException if an error occurred while creating the map projection.
 * @throws TransformException if an error occurred while projecting a point.
 */
@Test
public void testEllipse() throws FactoryException, TransformException {
    createCompleteProjection(new org.apache.sis.referencing.operation.provider.AlbersEqualArea(), // Semi-major axis from Snyder table 15
    CLARKE_A, // Semi-minor axis
    CLARKE_B, // Central meridian
    0, // Latitude of origin
    0, // Standard parallel 1 (from Snyder table 15)
    29.5, // Standard parallel 2 (from Snyder table 15)
    45.5, // Scale factor (none)
    NaN, // False easting
    0, // False northing
    0);
    // Approximately 100 metres.
    final double delta = toRadians(100.0 / 60) / 1852;
    derivativeDeltas = new double[] { delta, delta };
    toleranceModifier = ToleranceModifier.PROJECTION;
    tolerance = Formulas.LINEAR_TOLERANCE;
    final AlbersEqualArea kernel = (AlbersEqualArea) getKernel();
    assertFalse(isSpherical(kernel));
    /*
         * Expected 'n' value from Snyder table 15. The division by (1-ℯ²) is because Apache SIS omits this factor
         * in its calculation of n (we rather take it in account in (de)normalization matrices and elsewhere).
         */
    assertEquals(0.6029035, kernel.nm / (1 - kernel.eccentricitySquared), 0.5E-7);
    /*
         * When stepping into the AlbersEqualArea.Sphere.transform(…) method with a debugger, the expected
         * value of 6378206.4*ρ/(nm/(1-ℯ²)) is 6931335 (value taken from ρ column in Snyder table 15).
         */
    verifyTransform(new double[] { 0, 50 }, new double[] { 0, 5356698.435 });
    /*
         * Expect 6378206.4*ρ/(nm/(1-ℯ²))  ≈  8042164   (can be verified only with the debugger)
         */
    verifyTransform(new double[] { 0, 40 }, new double[] { 0, 4245869.390 });
    /*
         * Expect 6378206.4*ρ/(nm/(1-ℯ²))  ≈  9710969   (can be verified only with the debugger)
         */
    verifyTransform(new double[] { 0, 25 }, new double[] { 0, 2577064.350 });
    /*
         * Verify consistency with random points.
         */
    // Minimal input coordinate values
    verifyInDomain(// Minimal input coordinate values
    new double[] { -20, 20 }, // Maximal input coordinate values
    new double[] { +20, 50 }, // Number of points to test
    new int[] { 5, 5 }, TestUtilities.createRandomNumberGenerator());
}

