/**
 * Tests the WKT formatting of an Equirectangular projection. While the projection is implemented by
 * an affine transform, the WKT formatter should handle this projection in a special way and shows the
 * projection parameters instead of the affine transform parameters (except in "show internal" mode).
 *
 * @throws FactoryException if an error occurred while creating the map projection.
 */
@Test
public void testWKT() throws FactoryException {
    createCompleteProjection();
    assertWktEquals("PARAM_MT[“Equirectangular”,\n" + "  PARAMETER[“semi_major”, 6371007.0],\n" + "  PARAMETER[“semi_minor”, 6371007.0]]");
    /*
         * MathTransforms are not defined in WKT 2, so the following WKTs do not exist in standards.
         * Since the semi-major and semi-minor parameters do not have EPSG codes, the ID[…] elements
         * below show whatever identifier come first for each parameter (currently GeoTIFF identifiers,
         * but the authority may change in any future SIS version).
         */
    Assertions.assertWktEquals(Convention.WKT2, "PARAM_MT[“Equidistant Cylindrical (Spherical)”,\n" + "  PARAMETER[“semi_major”, 6371007.0, LENGTHUNIT[“metre”, 1], ID[“GeoTIFF”, 2057]],\n" + "  PARAMETER[“semi_minor”, 6371007.0, LENGTHUNIT[“metre”, 1], ID[“GeoTIFF”, 2058]]]", transform);
    Assertions.assertWktEquals(Convention.WKT2_SIMPLIFIED, "Param_MT[“Equidistant Cylindrical (Spherical)”,\n" + "  Parameter[“semi_major”, 6371007.0, Unit[“metre”, 1]],\n" + "  Parameter[“semi_minor”, 6371007.0, Unit[“metre”, 1]]]", transform);
    Assertions.assertWktEquals(Convention.INTERNAL, "Param_MT[“Affine parametric transformation”,\n" + "  Parameter[“A0”, 111195.04881760638, Id[“EPSG”, 8623]],\n" + "  Parameter[“B1”, 111195.04881760638, Id[“EPSG”, 8640]]]", transform);
}

