    0);
    final double[] coordinates = { 179, -41, 181, -41, -179, -41 };
    final double[] expected = { 6646679.62, -3767131.99, 6814949.99, -3767131.99, // This result was different before SIS-547 fix.
    6814949.99, // This result was different before SIS-547 fix.
    -3767131.99 };
    isInverseTransformSupported = false;
    tolerance = Formulas.LINEAR_TOLERANCE;
    verifyTransform(coordinates, expected);
    /*
         * Replace the 181° longitude by -179° so we can test reverse projection.
         */
    coordinates[2] = -179;
    isInverseTransformSupported = true;
    verifyTransform(coordinates, expected);
}

/**
 * Compares {@link MeridianArcBased#distance(double, double, double)} with formulas taken as references.
 */
@Test
public void compareWithReference() {
    final MeridianArcBased projection = create(true);
    final Random random = TestUtilities.createRandomNumberGenerator();
    for (int i = 0; i < 100; i++) {
        final double φ = random.nextDouble() * PI - PI / 2;
        final double reference = reference(projection, φ);
        final double accurate = referenceMoreAccurate(projection, φ);
        final double actual = projection.distance(φ, sin(φ), cos(φ));
        assertEquals(reference, accurate, 2E-10, "Accurate formula disagrees with reference.");
        assertEquals(accurate, actual, 1E-13, "Implementation disagrees with our formula.");
    }
}

