/**
 * Tests {@link WraparoundTransform#inverse()}.
 *
 * @throws TransformException if a coordinate cannot be computed.
 */
@Test
public void testInverse() throws TransformException {
    /*
         * Source range: [ 20 … 380]°.
         * Target range: [-90 … 270]°
         */
    final MathTransform forward = WraparoundTransform.create(3, 1, 360, 200, 90);
    final MathTransform inverse = forward.inverse();
    assertSame(forward, inverse.inverse());
    // Expect cached instance.
    assertSame(inverse, forward.inverse());
    final double[] sources = new double[] { 45, -100, 90, 60, -80, 70, 12, 300, 33 };
    final double[] targets = new double[9];
    forward.transform(sources, 0, targets, 0, 3);
    assertArrayEquals(new double[] { // Wraparound shall be applied.
    45, // Wraparound shall be applied.
    -100 + 360, // Wraparound shall be applied.
    90, // No wraparound because already in [-90 … 270]° range.
    60, // No wraparound because already in [-90 … 270]° range.
    -80, // No wraparound because already in [-90 … 270]° range.
    70, // Wraparound in opposite direction.
    12, // Wraparound in opposite direction.
    300 - 360, // Wraparound in opposite direction.
    33 }, targets);
    inverse.transform(sources, 0, targets, 0, 3);
    assertArrayEquals(new double[] { // Wraparound shall be applied.
    45, // Wraparound shall be applied.
    -100 + 360, // Wraparound shall be applied.
    90, // Idem.
    60, // Idem.
    -80 + 360, // Idem.
    70, // No wraparound because already in [ 20 … 380]° range.
    12, // No wraparound because already in [ 20 … 380]° range.
    300, // No wraparound because already in [ 20 … 380]° range.
    33 }, targets);
}

/**
 * Tests wraparound on one axis.
 *
 * @throws TransformException if a coordinate cannot be computed.
 */
@Test
public void testOneAxis() throws TransformException {
    final var op = new AbstractCoordinateOperation(Map.of(AbstractCoordinateOperation.NAME_KEY, "Wrapper"), HardCodedCRS.WGS84_LATITUDE_FIRST, HardCodedCRS.WGS84_LATITUDE_FIRST.forConvention(AxesConvention.POSITIVE_RANGE), null, MathTransforms.scale(3, 5));
    /*
         * Transform should be  [scale & normalization]  →  [wraparound]  →  [denormalization].
         * The wraparound is applied on target coordinates, which is why it appears after [scale].
         * Wrararound is often (but not always) unnecessary on source coordinates if the operation
         * uses trigonometric functions.
         */
    final MathTransform wt = WraparoundApplicator.forTargetCRS(op);
    final List<MathTransform> steps = MathTransforms.getSteps(wt);
    assertEquals(3, steps.size());
    assertEquals(1, ((WraparoundTransform) steps.get(1)).wraparoundDimension);
    /*
         * WraparoundTransform outputs are in [−180 … 180] range, so we expect
         * a 180° shift for getting results in the [0 … 360]° range.
         */
    assertMatrixEquals(new // Latitude (no wrap around)
    Matrix3(// Latitude (no wrap around)
    1, // Latitude (no wrap around)
    0, // Latitude (no wrap around)
    0, // Longitude in [0 … 360] range.
    0, // Longitude in [0 … 360] range.
    1, // Longitude in [0 … 360] range.
    180, 0, 0, 1), MathTransforms.getMatrix(steps.get(2)), STRICT, "denormalize");
    /*
         * The normalization is the inverse of above matrix.
         * But we expect the normalization matrix to be concatenated with the (3, 5) scale operation.
         */
    assertMatrixEquals(new // 3 is a factor in MathTransforms.scale(…).
    Matrix3(// 3 is a factor in MathTransforms.scale(…).
    3, // 3 is a factor in MathTransforms.scale(…).
    0, // 3 is a factor in MathTransforms.scale(…).
    0, // 5 is (idem).
    0, // 5 is (idem).
    5, // 5 is (idem).
    -180, 0, 0, 1), MathTransforms.getMatrix(steps.get(0)), STRICT, "normalize");
    /*
         * Test transforming some points.
         */
    final double[] pts = { 2, -100 / 5, 6, -200 / 5, 9, 200 / 5, 3, 400 / 5 };
    wt.transform(pts, 0, pts, 0, 4);
    assertArrayEquals(new double[] { 6, 260, 18, 160, 27, 200, 9, 40 }, pts);
}

