 * the default implementation, this is actually a test of {@code Resource.FileSet}.
 *
 * @throws DataStoreException if an error occurred while fetching the list of files.
 * @throws IOException if an error occurred while copying the file.
 */
@Test
public void testFileSet() throws DataStoreException, IOException {
    AsciiGridStore.FileSet fileset;
    try (AsciiGridStore store = new AsciiGridStore(null, testData(), true)) {
        fileset = store.getFileSet().orElseThrow();
    }
    final Path source = fileset.getPaths().iterator().next();
    assertEquals(FILENAME, source.getFileName().toString());
    /*
         * Tests the copy operation in a temporary directory.
         * This is using the default implementation of `FileSet.copy(…)`,
         */
    final Path dir = Files.createTempDirectory("sis-");
    Path target = null;
    try {
        target = fileset.copy(dir);
        assertEquals(dir, target.getParent());
        assertEquals(FILENAME, target.getFileName().toString());
        assertMultilinesEquals(Files.readString(source), Files.readString(target));
        /*
             * In order to test the delete operation, we need to open a new data store on the file
             * that we just copied. Otherwise, `fileset.delete()` would delete the original file.
             */
        try (AsciiGridStore store = new AsciiGridStore(null, new StorageConnector(target), true)) {
            fileset = store.getFileSet().orElseThrow();
        }
        fileset.delete();
        assertTrue(Files.notExists(target));
        target = null;
    } finally {
        if (target != null) {
            Files.deleteIfExists(target);
        }
        Files.deleteIfExists(dir);
    }
}

/**
 * Tests writing an ASCII Grid in a temporary file.
 *
 * @throws IOException if the temporary file cannot be created.
 * @throws DataStoreException if an error occurred while writing the file.
 */
@Test
public void testWriteInFile() throws IOException, DataStoreException {
    final GridCoverage coverage = createTestCoverage(HardCodedCRS.WGS84);
    final Path file = Files.createTempFile(null, ".asc");
    try {
        final Path filePRJ = toPRJ(file);
        final StorageConnector sc = new StorageConnector(file);
        sc.setOption(OptionKey.OPEN_OPTIONS, new StandardOpenOption[] { StandardOpenOption.WRITE });
        boolean deleted;
        try (WritableStore store = new WritableStore(null, sc)) {
            store.write(coverage);
            verifyContent(file);
            /*
                 * Verify that a second attempt to write the coverage fails,
                 * because now a coverage already exists.
                 */
            try {
                store.write(coverage);
                fail("Should not be allowed to overwrite an existing coverage.");
            } catch (ResourceAlreadyExistsException e) {
                assertNotNull(e.getMessage());
            }
            verifyContent(file);
            /*
                 * Write again, this time allowing the writer to replace the existing image.
                 */
            store.write(coverage, WritableStore.CommonOption.REPLACE);
            verifyContent(file);
            store.write(coverage, WritableStore.CommonOption.UPDATE);
            verifyContent(file);
        } finally {
            deleted = Files.deleteIfExists(filePRJ);
        }
        assertTrue(deleted, "Missing PRJ file.");
    } finally {
        Files.delete(file);
    }
}

