/**
 * Tests registration of converters from {@link String} to miscellaneous objects.
 * This method tests the addition of many converters because we want to observe
 * how {@linkplain #registry} grow in reaction to those additions.
 *
 * <p>This test compares the string representations for convenience.  In theory those string
 * representations are not committed API, so if the {@code FallbackConverter} implementation
 * change, it is okay to update this test accordingly.</p>
 */
@Test
public void testStringToMiscellaneous() {
    assertAllConvertersAreRegistered();
    register(new StringConverter.Short());
    assertSameConverterForTarget(Short.class);
    assertSameConverterForTarget(Number.class);
    assertIdentityForTarget(Object.class);
    assertNoConverterForTarget(Cloneable.class);
    assertIdentityForTarget(Comparable.class);
    assertIdentityForTarget(Serializable.class);
    assertMultilinesEquals("ConverterRegistry\n" + "  ├─Short         ← String\n" + // Same instance as above, applied to Number target.
    "  ├─Number        ← String\n" + "  │   └─Short     ← String\n" + "  ├─Object        ← String\n" + "  ├─Comparable    ← String\n" + "  └─Serializable  ← String\n", registry.toString(), "After StringConverter.Short");
    /*
         * Adds String ← Long
         * Expected side-effect: creation of FallbackConverter[String ← Number]
         */
    assertAllConvertersAreRegistered();
    assertNoConverterForTarget(Long.class);
    register(new StringConverter.Long());
    assertSameConverterForTarget(Long.class);
    assertIdentityForTarget(Object.class);
    assertNoConverterForTarget(Cloneable.class);
    assertIdentityForTarget(Comparable.class);
    assertIdentityForTarget(Serializable.class);
    assertFallbackEquals(Number.class, "Number    ← String\n" + "  ├─Short ← String\n" + "  └─Long  ← String\n");
    assertMultilinesEquals("ConverterRegistry\n" + "  ├─Short         ← String\n" + "  ├─Object        ← String\n" + "  ├─Comparable    ← String\n" + "  ├─Serializable  ← String\n" + "  ├─Long          ← String\n" + // The FallbackConverter, which replaced the previous.
    "  └─Number        ← String\n" + "      ├─Short     ← String\n" + "      └─Long      ← String\n", registry.toString(), "After StringConverter.Long");
    /*
         * Adds String ← Boolean
         * Expected side-effect: none since Boolean is not a Number
         */
    assertAllConvertersAreRegistered();
    assertNoConverterForTarget(Boolean.class);
    register(new StringConverter.Boolean());
    assertSameConverterForTarget(Boolean.class);
    assertIdentityForTarget(Object.class);
    assertNoConverterForTarget(Cloneable.class);
    assertIdentityForTarget(Comparable.class);
    assertIdentityForTarget(Serializable.class);
    assertMultilinesEquals("ConverterRegistry\n" + "  ├─Short         ← String\n" + "  ├─Object        ← String\n" + "  ├─Comparable    ← String\n" + "  ├─Serializable  ← String\n" + "  ├─Long          ← String\n" + "  ├─Number        ← String\n" + "  │   ├─Short     ← String\n" + "  │   └─Long      ← String\n" + "  └─Boolean       ← String\n", registry.toString(), "After StringConverter.Boolean");
    /*
         * Adds String ← Number
         * Expected side-effect: replacement of the FallbackConverter
         */
    assertAllConvertersAreRegistered();
    register(new StringConverter.Number());
    assertSameConverterForTarget(Number.class);
    assertIdentityForTarget(Object.class);
    assertNoConverterForTarget(Cloneable.class);
    assertIdentityForTarget(Comparable.class);
    assertIdentityForTarget(Serializable.class);
    assertMultilinesEquals("ConverterRegistry\n" + "  ├─Short         ← String\n" + "  ├─Object        ← String\n" + "  ├─Comparable    ← String\n" + "  ├─Serializable  ← String\n" + "  ├─Long          ← String\n" + "  ├─Boolean       ← String\n" + // Replaced the FallbackConverter.
    "  └─Number        ← String\n", registry.toString(), "After StringConverter.Number");
    /*
         * Adds String ← Float
         * Expected side-effect: none
         */
    assertAllConvertersAreRegistered();
    assertNoConverterForTarget(Float.class);
    register(new StringConverter.Float());
    assertSameConverterForTarget(Float.class);
    assertIdentityForTarget(Object.class);
    assertNoConverterForTarget(Cloneable.class);
    assertIdentityForTarget(Comparable.class);
    assertIdentityForTarget(Serializable.class);
    assertMultilinesEquals("ConverterRegistry\n" + "  ├─Short         ← String\n" + "  ├─Object        ← String\n" + "  ├─Comparable    ← String\n" + "  ├─Serializable  ← String\n" + "  ├─Long          ← String\n" + "  ├─Boolean       ← String\n" + "  ├─Number        ← String\n" + "  └─Float         ← String\n", registry.toString(), "After StringConverter.Float");
    /*
         * Final check.
         */
    assertAllConvertersAreRegistered();
}

/**
 * Tests registration of converters between {@link Number} and miscellaneous objects.
 * This method tests the addition of many converters because we want to observe
 * how {@linkplain #registry} grow in reaction to those additions.
 *
 * <p>This test compares the string representations for convenience.  In theory those string
 * representations are not committed API, so if the {@code FallbackConverter} implementation
 * change, it is okay to update this test accordingly.</p>
 */
@Test
public void testNumberToMiscellaneous() {
    assertAllConvertersAreRegistered();
    register(new StringConverter.Number().inverse());
    assertSameConverterForTarget(String.class);
    assertIdentityForTarget(Object.class);
    assertNoConverterForTarget(Cloneable.class);
    assertNoConverterForTarget(Comparable.class);
    assertIdentityForTarget(Serializable.class);
    assertSameConverterForTarget(CharSequence.class);
    assertMultilinesEquals("ConverterRegistry\n" + "  ├─String        ← Number\n" + "  ├─CharSequence  ← Number\n" + "  │   └─String    ← Number\n" + "  ├─Object        ← Number\n" + "  └─Serializable  ← Number\n", registry.toString(), "After ObjectToString.Number");
    /*
         * Adds String ← Number
         * Expected side-effect: none
         */
    assertAllConvertersAreRegistered();
    register(new StringConverter.Number());
    assertSameConverterForTarget(Number.class);
    assertMultilinesEquals("ConverterRegistry\n" + "  ├─String        ← Number\n" + "  ├─CharSequence  ← Number\n" + "  │   └─String    ← Number\n" + "  ├─Object        ← Number\n" + "  ├─Serializable  ← Number\n" + "  └─Number        ← String\n", registry.toString(), "After StringConverter.Number");
    /*
         * Adds Number ← Float
         * Expected side-effect: none
         */
    assertAllConvertersAreRegistered();
    register(new NumberConverter<>(Number.class, Float.class));
    assertSameConverterForTarget(Float.class);
    assertMultilinesEquals("ConverterRegistry\n" + "  ├─String        ← Number\n" + "  ├─CharSequence  ← Number\n" + "  │   └─String    ← Number\n" + "  ├─Object        ← Number\n" + "  ├─Serializable  ← Number\n" + "  ├─Number        ← String\n" + "  └─Float         ← Number\n", registry.toString(), "After NumberConverter.Float");
    /*
         * Final check.
         */
    assertAllConvertersAreRegistered();
}

