/**
 * Tests the field position while formatting an angle.
 */
@Test
public void testFieldPosition() {
    final Latitude latitude = new Latitude(FormattedCharacterIteratorTest.LATITUDE_VALUE);
    final AngleFormat f = new AngleFormat("DD°MM′SS.s″", Locale.CANADA);
    final StringBuffer buffer = new StringBuffer();
    for (int i = AngleFormat.DEGREES_FIELD; i <= AngleFormat.HEMISPHERE_FIELD; i++) {
        final AngleFormat.Field field;
        final int start, limit;
        switch(i) {
            case AngleFormat.DEGREES_FIELD:
                field = AngleFormat.Field.DEGREES;
                start = 0;
                limit = 3;
                break;
            case AngleFormat.MINUTES_FIELD:
                field = AngleFormat.Field.MINUTES;
                start = 3;
                limit = 6;
                break;
            case AngleFormat.SECONDS_FIELD:
                field = AngleFormat.Field.SECONDS;
                start = 6;
                limit = 11;
                break;
            case AngleFormat.HEMISPHERE_FIELD:
                field = AngleFormat.Field.HEMISPHERE;
                start = 11;
                limit = 12;
                break;
            // Skip the fraction field.
            default:
                continue;
        }
        final FieldPosition pos = new FieldPosition(field);
        assertEquals(FormattedCharacterIteratorTest.LATITUDE_STRING, f.format(latitude, buffer, pos).toString());
        assertSame(field, pos.getFieldAttribute());
        assertEquals(start, pos.getBeginIndex());
        assertEquals(limit, pos.getEndIndex());
        buffer.setLength(0);
    }
}

