 */
@Test
public void testCastOrCopy() {
    assertNull(CheckedArrayList.castOrCopy(null, String.class));
    final var fruits = List.of("Apple", "Orange", "Raisin");
    final var asStrings = CheckedArrayList.castOrCopy(fruits, String.class);
    // Should have the given element type.
    assertEquals(String.class, asStrings.getElementType());
    // Should have created a new instance.
    assertNotSame(fruits, asStrings);
    // Should contain the same data.
    assertEquals(fruits, asStrings);
    assertSame(asStrings, CheckedArrayList.castOrCopy(asStrings, String.class));
    final var asChars = CheckedArrayList.castOrCopy(asStrings, CharSequence.class);
    // Should have the given element type.
    assertEquals(CharSequence.class, asChars.getElementType());
    // Should have created a new instance.
    assertNotSame(asStrings, asChars);
    // Should contain the same data.
    assertEquals(asStrings, asChars);
    // Should contain the same data.
    assertEquals(fruits, asChars);
    var e = assertThrows(ClassCastException.class, () -> CheckedArrayList.castOrCopy(asChars, Integer.class), "Should not be allowed to cast String to Integer.");
    assertMessageContains(e, "String", "Integer");
}

