    final Filter<?> filter = CQL.parseFilter(cql);
    assertEquals(FF.or(FF.equal(FF.property("Title"), FF.literal("VMAI")), FF.and(FF.like(FF.property("Title"), "!$Pa_tt%ern?", '%', '_', '\\', false), FF.within(FF.property("BoundingBox"), FF.literal(baseGeometryPoint), Quantities.create(10, Units.METRE)))), filter);
}

