public void testOrAnd2() throws CQLException {
    final Geometry geom = GF.createPolygon(GF.createLinearRing(new Coordinate[] { new Coordinate(10, 40), new Coordinate(20, 40), new Coordinate(20, 30), new Coordinate(10, 30), new Coordinate(10, 40) }), new LinearRing[0]);
    final String cql = "NOT (INTERSECTS(BoundingBox, ENVELOPE(10, 20, 40, 30)) " + "OR CONTAINS(BoundingBox, POINT(12.1 28.9))) AND BBOX(BoundingBox, 10,20,30,40)";
    final Filter<?> filter = CQL.parseFilter(cql);
    assertEquals(FF.and(FF.not(FF.or(FF.intersects(FF.property("BoundingBox"), FF.literal(geom)), FF.contains(FF.property("BoundingBox"), FF.literal(baseGeometryPoint)))), FF.bbox(FF.property("BoundingBox"), new GeneralEnvelope(new Envelope2D(null, 10, 20, 30 - 10, 40 - 20)))), filter);
}

