        assertArrayEquals(new byte[] { 'S', 'Q', 'L', 'i', 't', 'e', ' ', 'f', 'o', 'r', 'm', 'a', 't', ' ', '3', 0x00 }, signature);
        ds.skip(68 - signature.length);
