        connector.setOption(OptionKey.OPEN_OPTIONS, new StandardOpenOption[] { StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE, StandardOpenOption.READ });
        try (GpkgStore store = new GpkgStore(null, connector)) {
            final var gpkg = assertInstanceOf(GpkgStore.class, store);
